window.PLANTUML_STDLIB.awslib20.awsexperimental=';!function $DefineCalloutSprite($number, $textcolor, $fillcolor, $x) ;!$header = \'sprite Callout_\' + $number + \' <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18">\';!$circle = \'<circle cx="9" cy="9" r="9" fill="\' + $fillcolor + \'" />\';!$textnumber = \'<text x="\' + $x + \'" y="13" fill="\' + $textcolor + \'" font-size="10">\' + $number + \'</text></svg>\';!return $header + $circle + $textnumber;!endfunction;;sprite Callout_SP <svg xmlns="http://www.w3.org/2000/svg" width="18" height="1"></svg>;;!$CalloutIndex = 1;!while $CalloutIndex < 100;  !if $CalloutIndex < 10;    $DefineCalloutSprite($CalloutIndex, $AWS_BG_COLOR, $AWS_FG_COLOR, 6);  !else;    $DefineCalloutSprite($CalloutIndex, $AWS_BG_COLOR, $AWS_FG_COLOR, 3);  !endif;  !$CalloutIndex = $CalloutIndex + 1;!endwhile;;skinparam note<<AWSIcon>> {;  FontColor $AWS_FG_COLOR;  BorderColor #Transparent;  BackgroundColor #Transparent;};!procedure $AWSIconNote($service, $label="", $side="left");note<<AWSIcon>> $side;   %call_user_func("$" + $service + "IMG", "0.5");!if %not($label == "");   $label;!endif;end note;!endprocedure ;;!procedure $AWSIconLeft($service, $label="");$AWSIconNote($service, $label, left);!endprocedure;;!procedure $AWSIconRight($service, $label="");$AWSIconNote($service, $label, right);!endprocedure'.split(";");
